class ResilioTechWebsite{constructor(){this.navbar=document.getElementById('navbar');this.navToggle=document.getElementById('nav-toggle');this.navMenu=document.getElementById('nav-menu');this.contactForm=document.getElementById('contact-form');this.init();}init(){this.setupNavigation();this.setupScrollEffects();this.setupSmoothScrolling();this.setupFormHandling();this.setupAnimations();this.setupPerformanceOptimizations();this.setupResourceCards();this.setupHomeResourcePosts();this.setupHomeProjects();}setupNavigation(){if(this.navToggle&&this.navMenu){this.navToggle.addEventListener('click',()=>{this.navMenu.classList.toggle('active');this.navToggle.classList.toggle('active');});const navLinks=this.navMenu.querySelectorAll('.nav-link');navLinks.forEach(link=>{link.addEventListener('click',()=>{this.navMenu.classList.remove('active');this.navToggle.classList.remove('active');});});document.addEventListener('click',(e)=>{if(!this.navToggle.contains(e.target)&&!this.navMenu.contains(e.target)){this.navMenu.classList.remove('active');this.navToggle.classList.remove('active');}});}this.highlightActiveNavLink();window.addEventListener('scroll',throttle(()=>{this.highlightActiveNavLink();},100));}setupScrollEffects(){let ticking=false;const updateScrollEffects=()=>{const scrollY=window.scrollY;if(this.navbar){if(scrollY>50){this.navbar.classList.add('scrolled');}else{this.navbar.classList.remove('scrolled');}}ticking=false;};const requestTick=()=>{if(!ticking){requestAnimationFrame(updateScrollEffects);ticking=true;}};window.addEventListener('scroll',requestTick);}setupSmoothScrolling(){document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',(e)=>{e.preventDefault();const target=document.querySelector(anchor.getAttribute('href'));if(target){const offsetTop=target.offsetTop-80;window.scrollTo({top: offsetTop,behavior: 'smooth'});}});});}setupFormHandling(){if(this.contactForm){this.contactForm.addEventListener('submit',(e)=>{e.preventDefault();this.handleFormSubmission();});const inputs=this.contactForm.querySelectorAll('input,textarea,select');inputs.forEach(input=>{input.addEventListener('blur',()=>this.validateField(input));input.addEventListener('input',()=>this.clearFieldError(input));});}}async handleFormSubmission(){const formData=new FormData(this.contactForm);const data=Object.fromEntries(formData);const isValid=this.validateForm();if(!isValid)return;const submitButton=this.contactForm.querySelector('button[type="submit"]');const originalText=submitButton.textContent;submitButton.textContent='Sending...';submitButton.disabled=true;try{await this.simulateFormSubmission(data);this.showFormMessage('Thank you!Your message has been sent successfully. We\'ll get back to you within 24 hours.','success');this.contactForm.reset();}catch(error){console.error('Form submission error:',error);this.showFormMessage('Sorry,there was an error sending your message. Please try again or email us directly at contact@resiliotech.com.','error');}finally{submitButton.textContent=originalText;submitButton.disabled=false;}}simulateFormSubmission(data){return new Promise((resolve,reject)=>{setTimeout(()=>{if(Math.random()>0.05){resolve();}else{reject(new Error('Simulated network error'));}},1500);});}validateForm(){const requiredFields=this.contactForm.querySelectorAll('[required]');let isValid=true;requiredFields.forEach(field=>{if(!this.validateField(field)){isValid=false;}});return isValid;}validateField(field){const value=field.value.trim();let isValid=true;let errorMessage='';if(field.hasAttribute('required')&&!value){isValid=false;errorMessage='This field is required';}if(field.type==='email'&&value){const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!emailRegex.test(value)){isValid=false;errorMessage='Please enter a valid email address';}}if(!isValid){this.showFieldError(field,errorMessage);}else{this.clearFieldError(field);}return isValid;}showFieldError(field,message){this.clearFieldError(field);const errorElement=document.createElement('span');errorElement.className='field-error';errorElement.textContent=message;errorElement.style.color='#ef4444';errorElement.style.fontSize='0.875rem';errorElement.style.marginTop='0.25rem';field.style.borderColor='#ef4444';field.parentNode.appendChild(errorElement);}clearFieldError(field){const existingError=field.parentNode.querySelector('.field-error');if(existingError){existingError.remove();}field.style.borderColor='';}showFormMessage(message,type){const existingMessage=this.contactForm.querySelector('.form-message');if(existingMessage){existingMessage.remove();}const messageElement=document.createElement('div');messageElement.className=`form-message form-message-${type}`;messageElement.textContent=message;messageElement.style.padding='1rem';messageElement.style.borderRadius='0.5rem';messageElement.style.marginTop='1rem';messageElement.style.fontSize='0.875rem';if(type==='success'){messageElement.style.backgroundColor='#dcfce7';messageElement.style.color='#166534';messageElement.style.border='1px solid #bbf7d0';}else{messageElement.style.backgroundColor='#fef2f2';messageElement.style.color='#dc2626';messageElement.style.border='1px solid #fecaca';}this.contactForm.appendChild(messageElement);setTimeout(()=>{if(messageElement.parentNode){messageElement.remove();}},10000);}highlightActiveNavLink(){const sections=document.querySelectorAll('section[id]');const navLinks=document.querySelectorAll('.nav-link');let currentSection='';const scrollPosition=window.scrollY+100;sections.forEach(section=>{const sectionTop=section.offsetTop;const sectionHeight=section.offsetHeight;if(scrollPosition>=sectionTop&&scrollPosition<sectionTop+sectionHeight){currentSection=section.getAttribute('id');}});navLinks.forEach(link=>{link.classList.remove('active');if(link.getAttribute('href')===`#${currentSection}`){link.classList.add('active');}});}setupAnimations(){const observerOptions={threshold: 0.1,rootMargin: '0px 0px-50px 0px'};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.style.opacity='1';entry.target.style.transform='translateY(0)';}});},observerOptions);document.querySelectorAll('[data-aos]').forEach(element=>{element.style.opacity='0';element.style.transform='translateY(30px)';element.style.transition='opacity 0.6s ease-out,transform 0.6s ease-out';observer.observe(element);});}setupPerformanceOptimizations(){if('IntersectionObserver' in window){const imageObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');}imageObserver.unobserve(img);}});});document.querySelectorAll('img[data-src]').forEach(img=>{imageObserver.observe(img);});}this.preloadCriticalResources();}preloadCriticalResources(){const criticalImages=[ 'assets/images/logo.svg' ];criticalImages.forEach(src=>{const link=document.createElement('link');link.rel='preload';link.as='image';link.href=src;document.head.appendChild(link);});}setupResourceCards(){const resourceCards=document.querySelectorAll('.resource-card');resourceCards.forEach(card=>{card.addEventListener('click',(e)=>{if(e.target.tagName==='A'||e.target.closest('a')){return;}const link=card.querySelector('.resource-link');if(link){window.open(link.href,'_blank','noopener,noreferrer');}});card.addEventListener('mouseenter',()=>{card.style.cursor='pointer';});});}setupHomeResourcePosts(){const homeResourcesGrid=document.getElementById('home-resources-grid');if(homeResourcesGrid&&typeof resourcesData!=='undefined'){const featuredPosts=resourcesData.getAllPosts().filter(post=>post.featured).slice(0,3);homeResourcesGrid.innerHTML=featuredPosts.map(post=>{const platformIcon=resourcesData.getPlatformIcon(post.platform);const platformName=resourcesData.getPlatformName(post.platform);return `<article class="resource-card" data-platform="${post.platform}" data-url="${post.url}"><div class="resource-thumbnail"><img src="${post.image}" alt="${post.title}" loading="lazy"><div class="resource-platform" title="${platformName}"><svg viewBox="0 0 24 24" fill="currentColor">${platformIcon}</svg></div></div><div class="resource-content"><h3 class="resource-title">${post.title}</h3><p class="resource-excerpt">${post.excerpt}</p><div class="resource-meta"><span class="resource-date">${post.date}</span><span class="resource-reading-time">${post.readingTime}</span></div><a href="${post.url}" class="resource-link" target="_blank" rel="noopener noreferrer">Read on ${platformName}</a></div></article>`;}).join('');const homeResourceCards=homeResourcesGrid.querySelectorAll('.resource-card');homeResourceCards.forEach(card=>{card.addEventListener('click',(e)=>{if(e.target.tagName==='A'||e.target.closest('a')){return;}const url=card.dataset.url;if(url){window.open(url,'_blank','noopener,noreferrer');}});});}}setupHomeProjects(){const homeProjectsGrid=document.getElementById('home-projects-grid');if(homeProjectsGrid&&typeof projectsData!=='undefined'){const latestProjects=getLatestProjects(3);homeProjectsGrid.innerHTML=latestProjects.map(project=>{const techTags=project.technologies.slice(0,3).map(tech=>`<span class="tech-tag">${tech}</span>`).join('');const outcomeKeys=Object.keys(project.outcomes);const outcomeElements=outcomeKeys.map(key=>{const label=key.replace(/([A-Z])/g,' $1').toLowerCase();const capitalizedLabel=label.charAt(0).toUpperCase()+label.slice(1);return `<div class="outcome"><span class="outcome-value">${project.outcomes[key]}</span><span class="outcome-label">${capitalizedLabel}</span></div>`;}).join('');return `<article class="project-card"><div class="project-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor">${this.getProjectIcon(project.icon)}</svg></div><div class="project-content"><h3 class="project-title">${project.title}</h3><p class="project-description">${project.description}</p><div class="project-technologies">${techTags}${project.technologies.length>3 ? '<span class="tech-tag">+'+(project.technologies.length-3)+' more</span>' : ''}</div></div><div class="project-outcomes">${outcomeElements}</div></article>`;}).join('');}}getProjectIcon(iconName){const icons={cloud: '<path d="M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z"></path>',settings: '<circle cx="12" cy="12" r="3"></circle><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1 1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"></path>',layers: '<polygon points="12,2 2,7 12,12 22,7 12,2"></polygon><polyline points="2,17 12,22 22,17"></polyline><polyline points="2,12 12,17 22,12"></polyline>',shield: '<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path>',cpu: '<rect x="4" y="4" width="16" height="16" rx="2"></rect><rect x="9" y="9" width="6" height="6"></rect><line x1="9" y1="1" x2="9" y2="4"></line><line x1="15" y1="1" x2="15" y2="4"></line><line x1="9" y1="20" x2="9" y2="23"></line><line x1="15" y1="20" x2="15" y2="23"></line><line x1="20" y1="9" x2="23" y2="9"></line><line x1="20" y1="14" x2="23" y2="14"></line><line x1="1" y1="9" x2="4" y2="9"></line><line x1="1" y1="14" x2="4" y2="14"></line>',lock: '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><circle cx="12" cy="16" r="1"></circle><path d="M7 11V7a5 5 0 0 1 10 0v4"></path>'};return icons[iconName]||icons.settings;}}function throttle(func,limit){let inThrottle;return function(){const args=arguments;const context=this;if(!inThrottle){func.apply(context,args);inThrottle=true;setTimeout(()=>inThrottle=false,limit);}};}function debounce(func,wait,immediate){let timeout;return function(){const context=this,args=arguments;const later=function(){timeout=null;if(!immediate)func.apply(context,args);};const callNow=immediate&&!timeout;clearTimeout(timeout);timeout=setTimeout(later,wait);if(callNow)func.apply(context,args);};}document.addEventListener('DOMContentLoaded',()=>{new ResilioTechWebsite();});document.addEventListener('visibilitychange',()=>{if(document.hidden){}else{}});window.addEventListener('error',(event)=>{console.error('JavaScript error:',event.error);});if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('/sw.js').then(registration=>{console.log('ServiceWorker registration successful');}).catch(error=>{console.log('ServiceWorker registration failed');});});}